const listExistingMachineIDs = `-- name: ListExistingMachineIDs :many
SELECT id FROM machines WHERE id = ANY($1::uuid[])
`

func (q *Queries) ListExistingMachineIDs(ctx context.Context, ids []uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listExistingMachineIDs, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

